-- Page id=29 ("Loading — Mark In Progress", GatePass entity): ship a new
-- page_version row rather than editing the current one in place, so the
-- prior body_json stays in history. Adds inline-editable Loading Location /
-- Loading Qty columns on the SKU line-items list (with balance_qty +
-- "Loaded Qty (live)" KPI recalculating on change), a route picker gating
-- Start Loading, and Stop Loading / Add Entry row actions.
--
-- Version number is computed from the existing max (not hardcoded) so this
-- is safe to run regardless of how many versions page 29 already has.
-- Guarded on body_json so re-running this file is a no-op if it already ran.
INSERT INTO page_version (page_id, version, status, body_json, published_at)
SELECT 29,
       (SELECT COALESCE(MAX(version), 0) + 1 FROM page_version WHERE page_id = 29),
       'PUBLISHED',
       '{"kind":"layout","schemaVersion":2,"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Loading — Mark In Progress","span":12,"subtitle":"Vehicles that have taken their first weight and are ready to load. Pick the gate pass (scan / pick / type), select a route, then Start Loading.","children":[{"kind":"Form","bindings":{"fields":[{"name":"gpNumber","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"LoadingSupervisor"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"vehicle_no":"vehicle_no","instanceId":"workflow_instance_id","route_id":"route_id","supervisor_name":"supervisor_name"}},{"name":"vehicle_no","label":"Vehicle","type":"text","readOnly":true},{"name":"route_id","label":"Route","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"OrderDispatchDetail","select":["route_id"],"distinct":true},"valueField":"route_id","labelField":"route_id"}}]}},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"▶ Start Loading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_IN_PROGRESS","color":"primary","visibleWhen":{"field":"form.route_id","op":"isNotEmpty"}},{"kind":"WorkflowActionButton","label":"📦 View Order","action":"page.open","page":"aria:loading-order","color":"secondary","args":{"params":{"route":"{{form.route_id}}"}}}]}]},{"kind":"Section","title":"Supervisor Status","span":12,"children":[{"kind":"Stack","direction":"row","gap":16,"children":[{"kind":"FormField","name":"supervisor_name","label":"Supervisor","type":"text","readOnly":true},{"kind":"KPI","label":"Loaded Qty (live)","unit":"units","live":true,"dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"},"aggregate":{"field":"loading_qty","fn":"sum"},"recalcOn":["listview.loading_qty.change"]}},{"kind":"KPI","label":"Order Qty","unit":"units","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"},"aggregate":{"field":"order_qty","fn":"sum"}}}]}]},{"kind":"Section","title":"Order / SKU Line Items","span":12,"children":[{"kind":"ListView","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"}},"selection":{"mode":"single","field":"selected","showCheckbox":true,"disableOthersOnSelect":true},"columns":[{"field":"sku_code","label":"SKU"},{"field":"description","label":"Description"},{"field":"loading_location","label":"Loading Location","widget_kind":"select","editable":true},{"field":"order_qty","label":"Order Qty","render":"number"},{"field":"loading_qty","label":"Loading Qty","render":"number","widget_kind":"number","editable":true,"onChange":{"recalc":["balance_qty","kpi.Loaded Qty (live)"]}},{"field":"balance_qty","label":"Balance Qty","render":"number"},{"field":"status","label":"Status","render":"badge","colorMap":{"LOADING_IN_PROGRESS":"green","PENDING":"orange","COMPLETED":"blue","SKIPPED":"red"}}],"rowActions":[{"label":"Stop Loading","action":"entity.update-field","args":{"field":"status","value":"PENDING"},"color":"error"},{"label":"Add Entry","action":"page.open","page":"aria:loading-add-entry","args":{"params":{"orderDispatchId":"{{row.id}}","skuCode":"{{row.sku_code}}"}},"color":"primary"}],"pageSize":25}]},{"kind":"Section","span":12,"children":[{"kind":"Stack","direction":"row","gap":12,"justify":"flex-end","children":[{"kind":"WorkflowActionButton","label":"✓ Completed","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_COMPLETED","color":"success"}]}]}]}]}',
       NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM page_version
  WHERE page_id = 29
    AND body_json = '{"kind":"layout","schemaVersion":2,"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Loading — Mark In Progress","span":12,"subtitle":"Vehicles that have taken their first weight and are ready to load. Pick the gate pass (scan / pick / type), select a route, then Start Loading.","children":[{"kind":"Form","bindings":{"fields":[{"name":"gpNumber","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"LoadingSupervisor"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"vehicle_no":"vehicle_no","instanceId":"workflow_instance_id","route_id":"route_id","supervisor_name":"supervisor_name"}},{"name":"vehicle_no","label":"Vehicle","type":"text","readOnly":true},{"name":"route_id","label":"Route","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"OrderDispatchDetail","select":["route_id"],"distinct":true},"valueField":"route_id","labelField":"route_id"}}]}},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"▶ Start Loading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_IN_PROGRESS","color":"primary","visibleWhen":{"field":"form.route_id","op":"isNotEmpty"}},{"kind":"WorkflowActionButton","label":"📦 View Order","action":"page.open","page":"aria:loading-order","color":"secondary","args":{"params":{"route":"{{form.route_id}}"}}}]}]},{"kind":"Section","title":"Supervisor Status","span":12,"children":[{"kind":"Stack","direction":"row","gap":16,"children":[{"kind":"FormField","name":"supervisor_name","label":"Supervisor","type":"text","readOnly":true},{"kind":"KPI","label":"Loaded Qty (live)","unit":"units","live":true,"dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"},"aggregate":{"field":"loading_qty","fn":"sum"},"recalcOn":["listview.loading_qty.change"]}},{"kind":"KPI","label":"Order Qty","unit":"units","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"},"aggregate":{"field":"order_qty","fn":"sum"}}}]}]},{"kind":"Section","title":"Order / SKU Line Items","span":12,"children":[{"kind":"ListView","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"gate_pass_id","op":"eq","value":"{{form.instanceId}}"}},"selection":{"mode":"single","field":"selected","showCheckbox":true,"disableOthersOnSelect":true},"columns":[{"field":"sku_code","label":"SKU"},{"field":"description","label":"Description"},{"field":"loading_location","label":"Loading Location","widget_kind":"select","editable":true},{"field":"order_qty","label":"Order Qty","render":"number"},{"field":"loading_qty","label":"Loading Qty","render":"number","widget_kind":"number","editable":true,"onChange":{"recalc":["balance_qty","kpi.Loaded Qty (live)"]}},{"field":"balance_qty","label":"Balance Qty","render":"number"},{"field":"status","label":"Status","render":"badge","colorMap":{"LOADING_IN_PROGRESS":"green","PENDING":"orange","COMPLETED":"blue","SKIPPED":"red"}}],"rowActions":[{"label":"Stop Loading","action":"entity.update-field","args":{"field":"status","value":"PENDING"},"color":"error"},{"label":"Add Entry","action":"page.open","page":"aria:loading-add-entry","args":{"params":{"orderDispatchId":"{{row.id}}","skuCode":"{{row.sku_code}}"}},"color":"primary"}],"pageSize":25}]},{"kind":"Section","span":12,"children":[{"kind":"Stack","direction":"row","gap":12,"justify":"flex-end","children":[{"kind":"WorkflowActionButton","label":"✓ Completed","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_COMPLETED","color":"success"}]}]}]}]}'
);

UPDATE page_definition pd
JOIN page_version pv ON pv.page_id = pd.id
   SET pd.current_version_id = pv.id
 WHERE pd.id = 29
   AND pv.version = (SELECT MAX(version) FROM page_version WHERE page_id = 29);
